<?php $pageTitle='Clubs'; require 'header.php'; $clubs=$pdo->query("SELECT c.*,u.name AS leader_name,(SELECT COUNT(*) FROM memberships m WHERE m.club_id=c.id) AS members FROM clubs c JOIN users u ON u.id=c.leader_id ORDER BY c.created_at DESC")->fetchAll(); ?>
<section class="page-intro"><span class="eyebrow">FIND YOUR COMMUNITY</span><h1>Explore student clubs</h1><p>Meet people who share your interests and find a place to belong.</p></section>
<div class="cards club-grid"><?php if(!$clubs): ?><div class="empty">No clubs have been added yet.</div><?php endif; ?><?php foreach($clubs as $c): ?><article class="club-card"><div class="club-icon">✦</div><span class="tag"><?=e($c['category']?:'Student community')?></span><h3><?=e($c['name'])?></h3><p><?=e($c['description'])?></p><div class="club-meta"><span><?= (int)$c['members']?> members</span><a class="text-link" href="club.php?id=<?=$c['id']?>">View club →</a></div></article><?php endforeach; ?></div>
<?php require 'footer.php'; ?>
